  let run=|limits:Limits,caller:u64|{let mut op=Budget::new(limits);let mut ad=SourceAdmission::default();let mut codec=FoundationCodec::new(profile.registry(),&empty,&mut ad).map_err(err)?;let result=op.with_depth_at_least(caller,|op|lower::document(&checked,&compiled.doc.package.schema,Category::Block,profile.registry(),op,&mut codec));assert_eq!(op.current_depth(),0);assert_eq!(*raw,saved);Ok::<_,String>((result,op))};
