  assert_eq!(normal,shifted);assert_eq!(b7.usage().depth,b0.usage().depth+7);
  let used=b7.usage();let mut stops=0;let mut successes=0;
  for (resource,amount,reason) in [(0,used.work,StopReason::WorkLimit),(1,used.allocation_units,StopReason::AllocationLimit),(2,used.source_bytes,StopReason::SourceLimit),(3,used.nodes,StopReason::NodeLimit),(4,used.depth,StopReason::DepthLimit)]{
   assert!(amount>0);
   for cap in [0,amount-1,amount]{let mut limits=budget().limits();match resource{0=>limits.work=cap,1=>limits.allocation_units=cap,2=>limits.source_bytes=cap,3=>limits.nodes=cap,_=>limits.depth=cap}
    let (result,mut op)=run(limits,7)?;
    if cap==amount{assert_eq!(result.map_err(err)?,normal);successes+=1;}else{assert!(matches!(result,Err(DocumentLowerError::Stopped(s)) if s==reason),"resource {resource} cap {cap}: {result:?}");assert_eq!(op.poll(),Err(reason));stops+=1;}
   }
  }
  let mut cancelled=budget();cancelled.cancel();let mut ad=SourceAdmission::default();let mut codec=FoundationCodec::new(profile.registry(),&empty,&mut ad).map_err(err)?;
  assert!(matches!(lower::document(&checked,&compiled.doc.package.schema,Category::Block,profile.registry(),&mut cancelled,&mut codec),Err(DocumentLowerError::Stopped(StopReason::Cancelled))));assert_eq!(*raw,saved);
  println!("independent exact limits: {stops} stops / {successes} successes; caller depth {} -> {}; source once {}; original tree unchanged / cancelled cause preserved",b0.usage().depth,b7.usage().depth,used.source_bytes);
  Ok(())
